import numpy as np
import datetime

def task_func(arr):
    arr_np = np.asarray(arr)

    def _reverse_words(x):
        if isinstance(x, str):
            return " ".join(x.split(" ")[::-1])
        return x

    return np.vectorize(_reverse_words, otypes=[object])(arr_np)
